import{_ as e,o as a,c as o,a as n}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const d=JSON.parse('{"title":"Лично мне текущая ситуация труда очень напоминает 90-е","description":"","frontmatter":{"site":"pro","title":"Лично мне текущая ситуация труда очень напоминает 90-е","date":"2026-10-11T00:00:00.000Z","source":"https://t.me/jfyi_ps/105","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-11-lichno-mne-tekuschaya-situatsiya-truda-ochen-napominaet"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лично мне текущая ситуация труда очень напоминает 90-е"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-11-lichno-mne-tekuschaya-situatsiya-truda-ochen-napominaet"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лично мне текущая ситуация труда очень напоминает 90-е"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лично мне текущая ситуация труда очень напоминает 90-е\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-11-lichno-mne-tekuschaya-situatsiya-truda-ochen-napominaet\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-11\\"}"]]},"headers":[],"relativePath":"posts/2026-10-11-lichno-mne-tekuschaya-situatsiya-truda-ochen-napominaet.md","filePath":"posts/2026-10-11-lichno-mne-tekuschaya-situatsiya-truda-ochen-napominaet.md"}'),i={name:"posts/2026-10-11-lichno-mne-tekuschaya-situatsiya-truda-ochen-napominaet.md"};function r(s,t,p,l,c,u){return a(),o("div",null,[...t[0]||(t[0]=[n("<p>Лично мне текущая ситуация труда очень напоминает 90-е. Вместо честной работы люди воруют автомобили через дырку в заборе и толкают за полцены.</p><p>Без гарантии, без SLA, без налогов и систем учета/мониторинга. Даже серийник спиливают (убирают клода из истории коммитов).</p><p>Всё это выглядит не совсем законно и не очень правильно.</p><p>Казалось бы, уже два года сотни тысяч людей имеют доступ к сверхразуму, который ускоряет работу в разы. А динозавры всё ещё в смоляной яме*.</p><ul><li>Взрывной рост объема говнокода, комментариев, документации, техдолг накапливается в 10 раз быстрее.</li><li>ИИ повышает индивидуальную эффективность, но снижает командную. Раньше хотя бы кто-то один в команде мог удержать весь контекст многих лет работы на проекте, теперь никто не может успеть за тем, что происходит. Особенно тестировщики и сопровождение.</li><li>Системное мышление предполагает мышление графами, а самое важное в системах - связи и швы. Нейросеть может собрать лоскутное одеяло, но за красоту и прочность швов отвечает человек. Графовые модели данных предполагают иной способ генерации - сложный граф нельзя собрать предугадыванием следующего символа.</li></ul><p>Повальная оптимизация ФОТ, начавшаяся в конце года повсеместно из-за набранных корпоративных кредитов под сумасшедший процент (у одного знакомого банка летом случилась капитализация триллион). Отдавать нечем, сокращают самых опытных, прожженных, заменяют знания на ИИ.</p><p>Этот медовый месяц может длиться три месяца, полгода, год, рынок пересоберётся, отсортирует тех, кто реально могёт. Остальные станут менеджерами.</p><p>Кстати, 14 октября исполнится ровно два месяца как я ищу работу. 21 год в ИТ - 8 лет системной инженерии (Fujitsu Private Cloud), 13 лет в разработке, 8 из них руковожу командами. В основном Enterprise. Решаю любые Hard-skills проблемы. От кода до процессов. Soft-skills-проблемы не решаю.</p><p>Как бы то ни было, я как кузнец, не могу не куя. В свободное время дорабатываю алго-трейдера с собственным классификатором русских новостей с само-коррекцией. Точность прогноза направления уже 65-70%. Ищу возможность применения знаний о мульти-агентных системах и информационной безопасности. Пока не нашёл подходящих задач.</p><ul><li>Фред Брукс, Мифический человеко-месяц</li></ul>",10)])])}const h=e(i,[["render",r]]);export{d as __pageData,h as default};
